function generate42Factions() {
	const rng = new SeededRNG(202642);
	const result = [];
	const coords = [];
	for (let i = 0; i < 42; i++) {
		let best = {
			x: 0,
			y: 0,
			z: 0
		};
		for (let attempt = 0; attempt < 120; attempt++) {
			const angle = i * 2.399963 + rng.range(-.35, .35);
			const r = 14 + Math.sqrt((i + .5) / 42) * 74 + rng.range(-4, 4);
			const clampedR = Math.min(88, Math.max(12, r));
			const x = Math.round(Math.cos(angle) * clampedR * 10) / 10;
			const z = Math.round(Math.sin(angle) * clampedR * 10) / 10;
			const y = Math.round(rng.range(-16, 16) * 10) / 10;
			const minDist = coords.reduce((m, c) => Math.min(m, Math.hypot(c.x - x, c.y - y, c.z - z)), 999);
			if (minDist >= 19 || attempt === 119) {
				best = {
					x,
					y,
					z
				};
				if (minDist >= 19) break;
			}
		}
		coords.push(best);
	}
	let idx = 0;
	for (const sp of SPECIES) {
		const pair = FACTION_META[sp.id];
		for (let p = 0; p < 2; p++) {
			const m = pair[p];
			const axis = m.axis === "Mercantil" || m.axis === "Militar" || m.axis === "Tradicionalistas" || m.axis === "Reformistas" ? m.axis : "Reformistas";
			const coord = coords[idx];
			const id = `fac_${sp.id}_${p + 1}`;
			result.push({
				id,
				name: m.name,
				speciesId: sp.id,
				lifeFormId: sp.lifeFormId,
				axis,
				techStyle: m.style,
				color: m.color,
				customs: m.customs,
				laws: m.laws,
				economyFocus: m.econ,
				capitalSystemId: `sys_cap_${idx}`,
				capitalCoord: coord,
				requiresLicenseOrRenown: Boolean(m.restricted),
				warsWith: [],
				alliedWith: []
			});
			idx++;
		}
	}
	const pairs = [];
	for (let i = 0; i < result.length; i++) for (let j = i + 1; j < result.length; j++) {
		const a = result[i];
		const b = result[j];
		const dist = Math.hypot(a.capitalCoord.x - b.capitalCoord.x, a.capitalCoord.y - b.capitalCoord.y, a.capitalCoord.z - b.capitalCoord.z);
		if (dist <= 54.5) pairs.push({
			a,
			b,
			dist
		});
	}
	const shuffled = rng.shuffle(pairs);
	let warCount = 0;
	let allyCount = 0;
	for (const { a, b, dist } of shuffled) {
		const sameSpecies = a.speciesId === b.speciesId;
		const sameLifeForm = a.lifeFormId === b.lifeFormId;
		const militaryPair = a.axis === "Militar" || b.axis === "Militar";
		const spA = SPECIES_BY_ID[a.speciesId];
		const spB = SPECIES_BY_ID[b.speciesId];
		const expansionistPair = spA.temperament === "expansionista" || spB.temperament === "expansionista";
		if (warCount < 15 && dist <= 54) {
			const warScore = (sameSpecies ? .12 : .45) * (militaryPair ? 1.5 : 1) * (expansionistPair ? 1.3 : 1);
			if (!sameLifeForm && rng.chance(warScore * .42)) {
				a.warsWith.push(b.id);
				b.warsWith.push(a.id);
				warCount++;
				continue;
			}
			if (sameSpecies && rng.chance(.12)) {
				a.warsWith.push(b.id);
				b.warsWith.push(a.id);
				warCount++;
				continue;
			}
		}
		if (allyCount < 19 && dist <= 46 && !a.warsWith.includes(b.id)) {
			const allyBias = (sameLifeForm ? .48 : .24) * (!militaryPair ? 1.25 : .7);
			if (rng.chance(allyBias)) {
				a.alliedWith.push(b.id);
				b.alliedWith.push(a.id);
				allyCount++;
			}
		}
	}
	for (const { a, b, dist } of shuffled) {
		if (warCount >= 15) break;
		if (a.warsWith.includes(b.id) || a.alliedWith.includes(b.id)) continue;
		if (a.speciesId !== b.speciesId && dist <= 54) {
			a.warsWith.push(b.id);
			b.warsWith.push(a.id);
			warCount++;
		}
	}
	for (const { a, b, dist } of shuffled) {
		if (allyCount >= 19) break;
		if (a.warsWith.includes(b.id) || a.alliedWith.includes(b.id)) continue;
		if (dist <= 46) {
			a.alliedWith.push(b.id);
			b.alliedWith.push(a.id);
			allyCount++;
		}
	}
	return result;
}
var FACTIONS = generate42Factions();
var FACTIONS_BY_ID = Object.fromEntries(FACTIONS.map((f) => [f.id, f]));
function isFactionConservative(factionOrId) {
	if (!factionOrId) return false;
	const fac = typeof factionOrId === "string" ? FACTIONS_BY_ID[factionOrId] : factionOrId;
	return Boolean(fac && fac.axis === "Tradicionalistas");
}
function getFactionDistanceLy(facAId, facBId) {
	const a = FACTIONS_BY_ID[facAId];
	const b = FACTIONS_BY_ID[facBId];
	if (!a || !b) return 999;
	return Math.hypot(a.capitalCoord.x - b.capitalCoord.x, a.capitalCoord.y - b.capitalCoord.y, a.capitalCoord.z - b.capitalCoord.z);
}
