var DEFAULT_ORIGIN_BONUSES = {
	combatDpsMult: 1,
	hullFlatBonus: 0,
	shieldCapMult: 1,
	shieldRegenMult: 1,
	hullRegenPerSec: 0,
	fuelCostMult: 1,
	cargoFlatBonus: 0,
	minerRateMult: 1,
	tradePriceBonus: 0,
	explorerBonus: 0,
	hazardResistBonus: 0,
	renownGainMult: 1,
	warScoreMult: 1,
	cloakBonus: 0,
	supplyCostMult: 1,
	fleeBonusPct: 0
};
function mergeOriginBonuses(base, delta) {
	if (!delta) return base;
	return {
		combatDpsMult: Math.round((base.combatDpsMult + ((delta.combatDpsMult ?? 1) - 1)) * 1e3) / 1e3,
		hullFlatBonus: base.hullFlatBonus + (delta.hullFlatBonus ?? 0),
		shieldCapMult: Math.round((base.shieldCapMult + ((delta.shieldCapMult ?? 1) - 1)) * 1e3) / 1e3,
		shieldRegenMult: Math.round((base.shieldRegenMult + ((delta.shieldRegenMult ?? 1) - 1)) * 1e3) / 1e3,
		hullRegenPerSec: Math.round((base.hullRegenPerSec + (delta.hullRegenPerSec ?? 0)) * 100) / 100,
		fuelCostMult: Math.max(.55, Math.round(base.fuelCostMult * (delta.fuelCostMult ?? 1) * 1e3) / 1e3),
		cargoFlatBonus: base.cargoFlatBonus + (delta.cargoFlatBonus ?? 0),
		minerRateMult: Math.round((base.minerRateMult + ((delta.minerRateMult ?? 1) - 1)) * 1e3) / 1e3,
		tradePriceBonus: Math.min(.4, Math.round((base.tradePriceBonus + (delta.tradePriceBonus ?? 0)) * 1e3) / 1e3),
		explorerBonus: base.explorerBonus + (delta.explorerBonus ?? 0),
		hazardResistBonus: base.hazardResistBonus + (delta.hazardResistBonus ?? 0),
		renownGainMult: Math.round((base.renownGainMult + ((delta.renownGainMult ?? 1) - 1)) * 1e3) / 1e3,
		warScoreMult: Math.round((base.warScoreMult + ((delta.warScoreMult ?? 1) - 1)) * 1e3) / 1e3,
		cloakBonus: Math.min(.35, Math.round((base.cloakBonus + (delta.cloakBonus ?? 0)) * 1e3) / 1e3),
		supplyCostMult: Math.max(.45, Math.round(base.supplyCostMult * (delta.supplyCostMult ?? 1) * 1e3) / 1e3),
		fleeBonusPct: Math.min(45, (base.fleeBonusPct ?? 0) + (delta.fleeBonusPct ?? 0))
	};
}
