function pickStarType(rng) {
	const total = STAR_TYPES_CONFIG.reduce((s, c) => s + c.weight, 0);
	let r = rng.next() * total;
	for (const cfg of STAR_TYPES_CONFIG) {
		r -= cfg.weight;
		if (r <= 0) return cfg;
	}
	return STAR_TYPES_CONFIG[0];
}
function getConflictFromChance(distToHostile) {
	if (distToHostile <= 16) return {
		level: 5,
		chancePct: 90
	};
	if (distToHostile <= 26) return {
		level: 4,
		chancePct: 70
	};
	if (distToHostile <= 38) return {
		level: 3,
		chancePct: 45
	};
	if (distToHostile <= 55) return {
		level: 2,
		chancePct: 22
	};
	return {
		level: 1,
		chancePct: 8
	};
}
function computeControllingFaction(x, y, z) {
	const distCenter = Math.hypot(x, y, z);
	let bestFaction = null;
	let bestDist = Infinity;
	for (const f of FACTIONS) {
		const d = Math.hypot(x - f.capitalCoord.x, y - f.capitalCoord.y, z - f.capitalCoord.z);
		if (d < bestDist) {
			bestDist = d;
			bestFaction = f.id;
		}
	}
	if (distCenter <= 98 && bestDist <= 21.75) return {
		factionId: bestFaction,
		nearestCapitalDist: bestDist
	};
	return {
		factionId: null,
		nearestCapitalDist: bestDist
	};
}
