function getLevelStyle(level, kind = "planet") {
	if (kind === "conflict") {
		if (level <= 1) return {
			badge: "bg-emerald-500/15 border-emerald-500/40 text-emerald-300",
			text: "text-emerald-300"
		};
		if (level === 2) return {
			badge: "bg-lime-500/15 border-lime-500/40 text-lime-300",
			text: "text-lime-300"
		};
		if (level === 3) return {
			badge: "bg-amber-500/15 border-amber-500/40 text-amber-300",
			text: "text-amber-300"
		};
		if (level === 4) return {
			badge: "bg-orange-500/15 border-orange-500/40 text-orange-300",
			text: "text-orange-300"
		};
		return {
			badge: "bg-rose-500/20 border-rose-500/60 text-rose-300",
			text: "text-rose-300"
		};
	}
	if (level < 0) return {
		badge: "bg-red-950/90 border-orange-500/75 text-orange-300",
		text: "text-orange-300"
	};
	if (level === 0) return {
		badge: "bg-slate-800/80 border-slate-700 text-slate-400",
		text: "text-slate-400"
	};
	if (level === 1) return {
		badge: "bg-teal-500/15 border-teal-500/40 text-teal-300",
		text: "text-teal-300"
	};
	if (level === 2) return {
		badge: "bg-emerald-500/15 border-emerald-500/40 text-emerald-300",
		text: "text-emerald-300"
	};
	if (level === 3) return {
		badge: "bg-sky-500/15 border-sky-500/40 text-sky-300",
		text: "text-sky-300"
	};
	if (level === 4) return {
		badge: "bg-purple-500/15 border-purple-500/40 text-purple-300",
		text: "text-purple-300"
	};
	return {
		badge: "bg-amber-500/20 border-amber-400/60 text-amber-300",
		text: "text-amber-300"
	};
}
var PLANET_LEVEL_LABELS = {
	[-1]: "Planeta Destruído",
	0: "Estéril",
	1: "Vida Primitiva",
	2: "Pré-Estelar",
	3: "Regional",
	4: "Avançado",
	5: "Sede Imperial"
};
var DAMAGE_TYPE_LABELS = {
	laser: "Laser",
	cinetica: "Cinética",
	plasma: "Plasma",
	missil: "Míssil"
};
var EXTRACTION_CLASS_LABELS = {
	broca_mineral: "Broca Mineral",
	coletor_atmosferico: "Coletor Atmosférico",
	bomba_liquida: "Bomba Líquida",
	coletor_biologico: "Coletor Biológico",
	extrator_energia: "Extrator de Energia",
	escavador_arqueologico: "Escavador Arqueológico"
};
function getEquipmentMeta(category, id) {
	if (category === "weapon") {
		const w = WEAPONS_BY_ID[id];
		if (!w) return {
			name: id,
			rarity: "comum",
			description: "",
			statsLine: ""
		};
		return {
			name: w.name,
			rarity: w.rarity,
			level: w.attackLevel,
			description: w.description,
			statsLine: `${DAMAGE_TYPE_LABELS[w.damageType]} · ${w.dps} DPS · Alcance ${w.range} · ${w.fireRate}/s${w.canBombard ? " · Bombardeio Orbital" : ""}`
		};
	}
	if (category === "shield") {
		const s = SHIELDS_BY_ID[id];
		if (!s) return {
			name: id,
			rarity: "comum",
			description: "",
			statsLine: ""
		};
		const refl = s.reflectDamageRatio ? ` · Reflete ${Math.round(s.reflectDamageRatio * 100)}%` : "";
		return {
			name: s.name,
			rarity: s.rarity,
			description: s.description,
			statsLine: `Escudo +${s.capacity} · Recarga ${s.rechargePerSec}/s · Mit. L ${Math.round(s.mitigation.laser * 100)}% / C ${Math.round(s.mitigation.cinetica * 100)}% / P ${Math.round(s.mitigation.plasma * 100)}% / M ${Math.round(s.mitigation.missil * 100)}%${refl}`
		};
	}
	if (category === "jumpDrive") {
		const j = JUMP_DRIVES_BY_ID[id];
		if (!j) return {
			name: id,
			rarity: "comum",
			description: "",
			statsLine: ""
		};
		return {
			name: j.name,
			rarity: j.rarity,
			description: j.description,
			statsLine: `Alcance ${j.jumpRangeLy} a.l. · Consumo ${Math.round(j.fuelEfficiency * 100)}%`
		};
	}
	if (category === "extractor") {
		const e = EXTRACTORS_BY_ID[id];
		if (!e) return {
			name: id,
			rarity: "comum",
			description: "",
			statsLine: ""
		};
		return {
			name: e.name,
			rarity: e.rarity,
			level: e.techTier,
			description: e.description,
			statsLine: `${EXTRACTION_CLASS_LABELS[e.extractionClass]} · ${e.ratePerSec.toFixed(1)} un./s`
		};
	}
	if (category === "utility") {
		const u = UTILITY_BY_ID[id];
		if (!u) return {
			name: id,
			rarity: "comum",
			description: "",
			statsLine: ""
		};
		return {
			name: u.name,
			rarity: u.rarity,
			description: u.description,
			statsLine: `Módulo de Utilidade`
		};
	}
	if (category === "suit") {
		const g = SUIT_GEAR_BY_ID[id];
		if (!g) return {
			name: id,
			rarity: "comum",
			description: "",
			statsLine: ""
		};
		return {
			name: g.name,
			rarity: g.rarity,
			description: g.description,
			statsLine: `Exploração +${g.explorationBonus} · Combate solo +${g.combatPower}`
		};
	}
	if (category === "hull") {
		const h = HULLS_BY_ID[id];
		if (!h) return {
			name: id,
			rarity: "comum",
			description: "",
			statsLine: ""
		};
		return {
			name: h.name,
			rarity: h.rarity,
			description: h.description,
			statsLine: `Casco ${h.maxHull} · Blindagem ${h.armor} · Carga ${h.cargoCapacity} · Comb. ${h.fuelCapacity} · Trip. ${h.activeCrewPosts}/${h.reserveQuarters}`
		};
	}
	const bp = BLUEPRINTS_BY_ID[id];
	if (!bp) return {
		name: id,
		rarity: "comum",
		description: "",
		statsLine: ""
	};
	return {
		name: bp.name,
		rarity: bp.minPlanetLevel >= 4 ? "lendário" : "raro",
		level: bp.minPlanetLevel,
		description: bp.description,
		statsLine: `Requer civilização ${bp.minPlanetLevel}+`
	};
}
