function getRarityFrameClass(rarity) {
	switch (rarity) {
		case "lendário": return "border-amber-400/70 bg-amber-950/35";
		case "épico": return "border-purple-400/60 bg-purple-950/35";
		case "raro": return "border-sky-400/55 bg-sky-950/35";
		case "incomum": return "border-emerald-400/50 bg-emerald-950/35";
		case "único": return "border-rose-400/70 bg-rose-950/35";
		default: return "border-slate-700/80 bg-slate-900/90";
	}
}
